265	    /**
266	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
267	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
268	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
269	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
270	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
271	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
272	     */
273	    private boolean normalizeAndValidateFields(Owner owner) {
274	        if (!normalizeAddressFields(owner)) {
275	            return false;
276	        }
277	        if (owner.getEmail() != null) {
278	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
279	            if (!EMAIL_PATTERN.matcher(email).matches()) {
280	                return false;
281	            }
282	            if (isDisposableEmailDomain(email)) {
283	                return false;
284	            }
285	            owner.setEmail(email);
286	        }
287	        if (!isPostcodeValidForCity(owner)) {
288	            return false;
289	        }
290	        String telephone = normalizeTelephone(owner.getTelephone());
291	        if (telephone == null) {
292	            return false;
293	        }
294	        owner.setTelephone(telephone);
295	        return true;
296	    }
