327	    /**
328	     * The domain part of {@code email} - everything after the last '@' - or {@code null} when the
329	     * value carries no '@'. The email is already normalized to lower case by the caller, so the
330	     * returned domain is lower-case and ready for a case-insensitive comparison. This is the single
331	     * place an email's domain is carved out, so the checks that compare a domain share it rather
332	     * than each re-scanning for the '@'.
333	     */
334	    private static String emailDomain(String email) {
335	        int at = email.lastIndexOf('@');
336	        return at < 0 ? null : email.substring(at + 1);
337	    }
338	
339	    /**
340	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
341	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
342	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
343	     */
344	    private static boolean isDisposableEmailDomain(String email) {
345	        String domain = emailDomain(email);
346	        return domain != null && DISPOSABLE_EMAIL_DOMAINS.contains(domain);
347	    }
348	
349	    /**
350	     * The registrable second-level labels of the {@link #DISPOSABLE_EMAIL_DOMAINS disposable domains}
351	     * (the label before the final TLD, e.g. {@code "mailinator.com" -> "mailinator"}), used to detect
352	     * domains that are merely disposable-adjacent rather than an exact blocklist match.
353	     */
354	    private static final Set<String> DISPOSABLE_DOMAIN_LABELS = DISPOSABLE_EMAIL_DOMAINS.stream()
355	        .map(OwnerRestControllerV1::secondLevelLabel)
356	        .collect(java.util.stream.Collectors.toUnmodifiableSet());
357	
358	    /**
359	     * The second-level label of {@code domain}: the dot-delimited label immediately before the final
360	     * TLD segment (e.g. {@code "x.mailinator.com" -> "mailinator"}, {@code "mailinator" -> "mailinator"}).
361	     */
362	    private static String secondLevelLabel(String domain) {
363	        String[] labels = domain.split("\\.");
364	        return labels.length >= 2 ? labels[labels.length - 2] : labels[labels.length - 1];
365	    }
366	
367	    /**
368	     * Whether {@code email}'s domain is disposable-adjacent: it is, is a subdomain of, or shares its
369	     * second-level label with a {@link #DISPOSABLE_EMAIL_DOMAINS known disposable domain} - so
370	     * {@code mailinator.com} (exact), {@code x.mailinator.com} (subdomain) and {@code mailinator.net}
371	     * (same label, different TLD) all match, while an unrelated domain does not. A softer signal than
372	     * the exact {@link #isDisposableEmailDomain(String) blocklist} the create gate rejects on, this
373	     * feeds the read-time {@link #isRiskFlag(Owner) risk flag}. A null or {@code '@'}-less email never
374	     * matches.
375	     */
376	    private static boolean isDisposableAdjacentDomain(String email) {
377	        if (email == null) {
378	            return false;
379	        }
380	        String domain = emailDomain(email.trim().toLowerCase(Locale.ROOT));
381	        return domain != null && DISPOSABLE_DOMAIN_LABELS.contains(secondLevelLabel(domain));
382	    }
