384	    /**
385	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
386	     * computed against the owner population rather than carried on the owner itself (currently the
387	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
388	     * listing intentionally omits these flags.
389	     */
390	    private OwnerDto buildOwnerDto(Owner owner) {
391	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
392	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
