398	    /**
399	     * Whether {@code owner} should be surfaced as a risk on read: true when any of the risk signals
400	     * hold - the owner is a possible duplicate ({@link Owner#getPossibleDuplicate()}), the owner's
401	     * email domain is {@link #isDisposableAdjacentDomain(String) disposable-adjacent}, or the owner's
402	     * city is over its soft capacity ({@link #isCapacityWarning(Owner)}); otherwise false. Each signal
403	     * reuses the rule that owns it rather than re-deriving it here.
404	     */
405	    private boolean isRiskFlag(Owner owner) {
406	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
407	            || isDisposableAdjacentDomain(owner.getEmail())
408	            || isCapacityWarning(owner);
409	    }
