411	    /**
412	     * Whether {@code owner}'s city is approaching its per-city capacity limit: it already holds between
413	     * 40 and 49 other owners, one short of the hard limit of 50 at which creation is rejected.
414	     * Surfaced on responses as {@code capacityWarning}. Computed against the current owner population
415	     * excluding this owner, so the count basis mirrors the per-city create gate (which counts the
416	     * owners already present, before the new one is added).
417	     */
418	    private boolean isCapacityWarning(Owner owner) {
419	        long othersInCity = countOtherOwnersInCity(owner);
420	        return othersInCity >= CITY_SOFT_CAPACITY && othersInCity < CITY_HARD_CAPACITY;
421	    }
