525	    /** Matches a well-formed postcode: exactly 4 digits. */
526	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
527	
528	    /**
529	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
530	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
531	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
532	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
533	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
534	     */
535	    private static boolean isPostcodeValidForCity(Owner owner) {
536	        String postcode = owner.getPostcode();
537	        if (postcode == null) {
538	            return true;
539	        }
540	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
541	            return false;
542	        }
543	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
544	        if (range == null) {
545	            return true;
546	        }
547	        int value = Integer.parseInt(postcode);
548	        return value >= range[0] && value <= range[1];
549	    }
550	
551	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
552	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
553	
554	    /**
555	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
556	     * code are kept when present; otherwise country code '+61' is assumed and a single
557	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
558	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
559	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
560	     * Returns {@code null} when the number cannot form a valid E.164 value.
561	     */
562	    private static String normalizeTelephone(String telephone) {
563	        if (telephone == null) {
564	            return null;
565	        }
566	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
567	        String e164;
568	        if (cleaned.startsWith("+")) {
569	            e164 = cleaned;
570	        } else {
571	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
572	            e164 = "+61" + national;
573	        }
574	        if (!E164_PATTERN.matcher(e164).matches()) {
575	            return null;
576	        }
577	        return hasValidNationalNumberLength(e164) ? e164 : null;
578	    }
579	
580	    /**
581	     * Whether the national number of a well-formed E.164 value has the length required for its
582	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
583	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
584	     */
585	    private static boolean hasValidNationalNumberLength(String e164) {
586	        String countryCode = Owner.countryCodeOf(e164);
587	        if (countryCode == null) {
588	            return true;
589	        }
590	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
591	    }
