593	    /**
594	     * Compute and assign the derived attributes carried by a newly registered owner: the member id,
595	     * household id, namesake count and household member count. Each is derived from the owner's
596	     * already-normalized fields and the existing owner population, so this must run before the owner
597	     * is saved, while the counts still exclude the owner being created.
598	     *
599	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
600	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
601	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
602	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
603	     */
604	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
605	        owner.setMemberId(generateMemberId(owner));
606	        owner.setHouseholdId(householdId(owner));
607	        owner.setNamesakeCount(countNamesakes(owner));
608	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
609	        owner.setMembershipLevelCap(membershipLevelCapForHousehold(owner));
610	        if (declaredMember) {
611	            owner.setPossibleDuplicate(false);
612	            owner.setPossibleDuplicateOf(null);
613	        } else {
614	            assignPossibleDuplicate(owner);
615	        }
616	    }
617	
618	    /**
619	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
620	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's postcode
621	     * and last-name {@link #soundex(String) Soundex} yet resolves to a different {@link #identityKey}.
622	     * Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf} to the
623	     * matching owner's id. Runs before save, against the existing owner population.
624	     */
625	    private void assignPossibleDuplicate(Owner owner) {
626	        Integer matchId = findPossibleDuplicateOf(owner);
627	        owner.setPossibleDuplicate(matchId != null);
628	        owner.setPossibleDuplicateOf(matchId);
629	    }
630	
631	    /**
632	     * The id of an existing owner that shares {@code owner}'s postcode and last-name
633	     * {@link #soundex(String) Soundex} but resolves to a different {@link #identityKey}, or
634	     * {@code null} when there is none. Because the telephone is part of the identity key, two owners
635	     * with the same last name and postcode but different telephones differ in key and so match here,
636	     * making the later a soft (possible) duplicate rather than a hard conflict. When several match,
637	     * the lowest id is returned. An owner without a postcode never matches.
638	     */
639	    private Integer findPossibleDuplicateOf(Owner owner) {
640	        String postcode = owner.getPostcode();
641	        if (postcode == null) {
642	            return null;
643	        }
644	        String soundex = soundex(owner.getLastName());
645	        String identityKey = owner.getIdentityKey();
646	        return this.clinicService.findAllOwners().stream()
647	            .filter(existing -> !existing.isDeleted())
648	            .filter(existing -> existing.getId() != null
649	                && postcode.equals(existing.getPostcode())
650	                && soundex(existing.getLastName()).equals(soundex)
651	                && !identityKey.equals(existing.getIdentityKey()))
652	            .map(Owner::getId)
653	            .min(Integer::compareTo)
654	            .orElse(null);
655	    }
656	
657	    /**
658	     * Build {@code owner}'s member id '<REGION><FY><HASH8><CHK>': REGION is the region code derived
659	     * from the owner's postcode ({@link Owner#getRegion()}), FY the two-digit
660	     * {@link Owner#fiscalYearSegment(LocalDate) fiscal-year segment} of the business-day-adjusted
661	     * {@link Owner#getRegistrationDate() registration date}, HASH8 the first 8 upper-case hex
662	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
663	     * owner's last name, and CHK a single {@link Owner#luhnCheckDigit(String) Luhn check digit} over
664	     * the digits of '<REGION><FY><HASH8>' (e.g. 'NSW271A2B3C4D5'). The identity is otherwise a pure
665	     * function of the region, fiscal year and the (telephone, last name) pair; only when the computed
666	     * id collides with an existing owner's member id is it de-duplicated by appending '-<n>' with the
667	     * smallest {@code n} of 2 or more that makes it unique (e.g. 'NSW271A2B3C4D5-2').
668	     */
669	    private String generateMemberId(Owner owner) {
670	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
671	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
672	        String hash8 = Owner.sha256Hex(telephone + lastName).substring(0, 8);
673	        String core = owner.getRegion() + Owner.fiscalYearSegment(owner.getRegistrationDate()) + hash8;
674	        String base = core + Owner.luhnCheckDigit(core);
675	        return deduplicateMemberId(base);
676	    }
677	
678	    /**
679	     * De-duplicate a computed member id against the existing owner population: when {@code base}
680	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
681	     * {@code n} of 2 or more that yields an id no existing owner carries.
682	     */
683	    private String deduplicateMemberId(String base) {
684	        Set<String> existing = this.clinicService.findAllOwners().stream()
685	            .map(Owner::getMemberId)
686	            .filter(code -> code != null)
687	            .collect(java.util.stream.Collectors.toSet());
688	        if (!existing.contains(base)) {
689	            return base;
690	        }
691	        int n = 2;
692	        while (existing.contains(base + "-" + n)) {
693	            n++;
694	        }
695	        return base + "-" + n;
696	    }
