698	    /**
699	     * The number of existing owners registered in {@code city}, compared case-insensitively
700	     * with collapsed whitespace.
701	     */
702	    private int countOwnersInCity(String city) {
703	        String normalized = normalizeHouseholdField(city);
704	        return (int) this.clinicService.findAllOwners().stream()
705	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
706	            .count();
707	    }
708	
709	    /**
710	     * The number of existing owners in {@code owner}'s city other than {@code owner} itself, compared
711	     * case-insensitively with collapsed whitespace. This is the count of owners already present in the
712	     * city that a newly created owner joins, mirroring the basis of the per-city create gate.
713	     */
714	    private long countOtherOwnersInCity(Owner owner) {
715	        String normalized = normalizeHouseholdField(owner.getCity());
716	        return this.clinicService.findAllOwners().stream()
717	            .filter(existing -> existing.getId() == null || !existing.getId().equals(owner.getId()))
718	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
719	            .count();
720	    }
721	
722	    /**
723	     * The effective registration date to store for a new owner: the date supplied on the request
724	     * when present, otherwise the current server date, in either case rolled forward to a business
725	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
726	     * This single point of resolution is what every registration-date-derived value (the stored
727	     * date, the member id's fiscal-year segment, the per-day create-limit) is computed from.
728	     */
729	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
730	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
731	        return toBusinessDay(date);
732	    }
733	
734	    /**
735	     * The fixed list of public holidays that a registration date must not fall on. A date landing
736	     * on one of these is rolled forward, exactly as weekends are.
737	     */
738	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
739	        LocalDate.of(2026, 1, 1),
740	        LocalDate.of(2026, 1, 26),
741	        LocalDate.of(2026, 4, 25),
742	        LocalDate.of(2026, 12, 25),
743	        LocalDate.of(2026, 12, 28));
744	
745	    /**
746	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
747	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
748	     * unchanged.
749	     */
750	    private static LocalDate toBusinessDay(LocalDate date) {
751	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
752	                || PUBLIC_HOLIDAYS.contains(date)) {
753	            date = date.plusDays(1);
754	        }
755	        return date;
756	    }
757	
758	    /**
759	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
760	     * last name, compared case-insensitively.
761	     */
762	    private int countNamesakes(Owner owner) {
763	        String firstName = normalizeHouseholdField(owner.getFirstName());
764	        String lastName = normalizeHouseholdField(owner.getLastName());
765	        return (int) this.clinicService.findAllOwners().stream()
766	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
767	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
768	            .count();
769	    }
770	
771	    /**
772	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
773	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
774	     * unusually high daily signup volume.
775	     */
776	    private boolean isBulkSignupWarning() {
777	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
778	    }
779	
780	    /** The number of existing owners whose registration date is {@code date}. */
781	    private int countOwnersRegisteredOn(LocalDate date) {
782	        return (int) this.clinicService.findAllOwners().stream()
783	            .filter(existing -> date.equals(existing.getRegistrationDate()))
784	            .count();
785	    }
786	
787	    /**
788	     * The single derived key all duplicate detection flows through: the lower-case hex SHA-256 of
789	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, formed from the
790	     * owner's already-normalized fields (the email is already lower-cased, the telephone already in
791	     * E.164 form, and the last name reduced to its {@link #soundex(String) Soundex} code). Because
792	     * the telephone is part of the key, two owners with the same last name and postcode but
793	     * different telephones resolve to different keys and are both allowed (the later one becoming a
794	     * possible duplicate rather than a hard conflict).
795	     */
796	    private static String identityKey(Owner owner) {
797	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
798	        String email = owner.getEmail() == null ? "" : owner.getEmail();
799	        String key = telephone + "|" + email + "|" + soundex(owner.getLastName());
800	        return Owner.sha256HexLower(key);
801	    }
802	
803	    /**
804	     * Whether {@code owner}'s {@link #identityKey} equals a non-deleted existing owner's, which is
805	     * the sole duplicate condition: the previously separate telephone, email and household checks -
806	     * including the household-duplicate check derived from the {@code householdId} - are now all
807	     * expressed through this one identity key, so only an exact key match is a duplicate and a create
808	     * that trips it is rejected with {@code 409 CONFLICT}. Soft-deleted owners are ignored.
809	     */
810	    private boolean isDuplicate(Owner owner) {
811	        String key = owner.getIdentityKey();
812	        return this.clinicService.findAllOwners().stream()
813	            .filter(existing -> !existing.isDeleted())
814	            .map(Owner::getIdentityKey)
815	            .filter(existing -> existing != null)
816	            .anyMatch(key::equals);
817	    }
818	
819	    /** Common street-type abbreviations expanded during address normalization. */
820	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
821	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
822	
823	    /**
824	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
825	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
826	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
827	     * string when {@code address} is null or blank after normalization.
828	     */
829	    private static String normalizeAddress(String address) {
830	        if (address == null) {
831	            return "";
832	        }
833	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
834	        if (collapsed.isEmpty()) {
835	            return "";
836	        }
837	        StringBuilder sb = new StringBuilder(collapsed.length());
838	        for (String token : collapsed.split(" ")) {
839	            if (sb.length() > 0) {
840	                sb.append(' ');
841	            }
842	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
843	        }
844	        return sb.toString();
845	    }
846	
847	    /**
848	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
849	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
850	     */
851	    private static String normalizeHouseholdField(String value) {
852	        if (value == null) {
853	            return "";
854	        }
855	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
856	    }
857	
858	    /**
859	     * The American Soundex code of {@code value}: the retained first letter followed by up to three
860	     * digits encoding the remaining consonants, right-padded with zeros to length four. Non-letters
861	     * are ignored, adjacent letters coding to the same digit (including when separated by 'H' or 'W')
862	     * are coded once, and vowels (with 'Y') act as separators. Returns the empty string when
863	     * {@code value} holds no letters. Phonetically similar last names share a code, which is what the
864	     * identity key and the possible-duplicate soft match compare on.
865	     */
866	    private static String soundex(String value) {
867	        if (value == null) {
868	            return "";
869	        }
870	        StringBuilder letters = new StringBuilder();
871	        for (char c : value.toCharArray()) {
872	            if (c < 128 && Character.isLetter(c)) {
873	                letters.append(Character.toUpperCase(c));
874	            }
875	        }
876	        if (letters.length() == 0) {
877	            return "";
878	        }
879	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
880	        char previous = soundexDigit(letters.charAt(0));
881	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
882	            char c = letters.charAt(i);
883	            if (c == 'H' || c == 'W') {
884	                continue;
885	            }
886	            char digit = soundexDigit(c);
887	            if (digit != '0' && digit != previous) {
888	                code.append(digit);
889	            }
890	            previous = digit;
891	        }
892	        while (code.length() < 4) {
893	            code.append('0');
894	        }
895	        return code.toString();
896	    }
897	
898	    /** The Soundex digit for an upper-case letter, or {@code '0'} for letters that are not coded. */
899	    private static char soundexDigit(char c) {
900	        switch (c) {
901	            case 'B': case 'F': case 'P': case 'V':
902	                return '1';
903	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
904	                return '2';
905	            case 'D': case 'T':
906	                return '3';
907	            case 'L':
908	                return '4';
909	            case 'M': case 'N':
910	                return '5';
911	            case 'R':
912	                return '6';
913	            default:
914	                return '0';
915	        }
916	    }
917	
918	    /**
919	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
920	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
921	     * key rather than re-derived from the underlying fields here, so the household is described in one
922	     * place and every household-keyed value stays consistent with it.
923	     */
924	    private List<Owner> findHousemates(Owner owner) {
925	        String householdId = householdId(owner);
926	        return this.clinicService.findAllOwners().stream()
927	            .filter(existing -> !existing.isDeleted())
928	            .filter(existing -> householdId(existing).equals(householdId))
929	            .toList();
930	    }
931	
932	    /**
933	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
934	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
935	     */
936	    private int countHouseholdMembers(Owner owner) {
937	        return findHousemates(owner).size() + 1;
938	    }
939	
940	    /**
941	     * The membership level ceiling for a newly registered {@code owner}, derived from the household it
942	     * joins: one above the current maximum {@link Owner#getMembershipLevel() membershipLevel} among the
943	     * existing housemates (owners sharing the same {@code householdId}), so a new owner's reported level
944	     * can never exceed one above the household's current best. Returns {@code null} - meaning no ceiling
945	     * applies - when the owner has no existing household member.
946	     */
947	    private Integer membershipLevelCapForHousehold(Owner owner) {
948	        OptionalInt maxLevel = findHousemates(owner).stream()
949	            .mapToInt(Owner::getMembershipLevel)
950	            .max();
951	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
952	    }
953	
954	    /**
955	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
956	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
957	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
958	     * string standing in for a missing postcode), so housemates always resolve to the same value
959	     * regardless of registration order, and owners sharing a last name and postcode share it
960	     * automatically.
961	     */
962	    private static String householdId(Owner owner) {
963	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
964	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
965	        return Owner.sha256Hex(key).substring(0, 12);
966	    }
967	}
